#include <stdio.h>

int square(int n) { return n * n; }
int max_of(int a, int b) { return a > b ? a : b; }
void line(int n) { for (int i = 0; i < n; i++) putchar('-'); putchar('\n'); }

int main(void) {
    printf("%d %d\n", square(6), max_of(3, 9));
    line(7);
    return 0;
}

#include <stdio.h>

int next_id(void) { static int id = 100; return ++id; }
void minmax(const int *a, int n, int *lo, int *hi) {
    *lo = *hi = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *lo) *lo = a[i];
        if (a[i] > *hi) *hi = a[i];
    }
}
int main(void) {
    printf("%d %d\n", next_id(), next_id());
    int v[] = {4, 9, 1, 7}, lo, hi;
    minmax(v, 4, &lo, &hi);
    printf("min=%d max=%d\n", lo, hi);
    return 0;
}

