lab.solution:
#include <stdio.h>
int add(int a,int b){return a+b;}
int sub(int a,int b){return a-b;}
int mul(int a,int b){return a*b;}
double divide(int a,int b){ return b ? (double)a/b : 0; }
int main(void){
    printf("add=%d sub=%d mul=%d div=%.2f\n", add(5,2), sub(5,2), mul(5,2), divide(5,2));
    if (0) printf("error: divide by zero\n");
    return 0;
}
